// 라우트 매칭 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const routes = [{ method: "GET", pattern: /^\/users\/(\d+)$/ }];
const request = { method: "GET", url: "/users/42" };
const matched = routes.find(r => r.method === request.method && r.pattern.test(request.url));
console.log(Boolean(matched));

// 미들웨어 체인 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const chain = [
  ctx => { ctx.steps.push("log"); return ctx; },
  ctx => { ctx.steps.push("auth"); return ctx; }
];
const result = chain.reduce((ctx, fn) => fn(ctx), { steps: [] });
console.log(result.steps.join(" -> "));

// 요청 객체(Request) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const request = { method: "POST", url: "/login", headers: { "content-type": "application/json" }, body: { id: "ada" } };
console.log(request.method, request.url, request.body.id);

// 응답 객체(Response) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const response = { status: 200, headers: { "content-type": "application/json" }, body: { ok: true } };
console.log(JSON.stringify(response.body));

// HTTP 메서드(GET/POST/PUT/DELETE) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const handlers = { GET: "조회", POST: "생성", PUT: "전체 수정", DELETE: "삭제" };
console.log(handlers["POST"]);

// 상태 코드(200/404/500) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const messages = { 200: "OK", 404: "Not Found", 500: "Server Error" };
const status = 404;
console.log(messages[status]);

// 헤더(Header) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const headers = { "content-type": "application/json", authorization: "Bearer token" };
console.log(headers["content-type"]);

// 쿠키(Cookie) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const cookie = "sessionId=abc123; theme=dark";
const pairs = Object.fromEntries(cookie.split("; ").map(v => v.split("=")));
console.log(pairs.theme);

// 세션(Session) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const sessions = new Map();
sessions.set("sid-1", { userId: 7, loggedIn: true });
console.log(sessions.get("sid-1").loggedIn);

// CORS 자격 증명 요청 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const request = { origin: "https://app.example", credentials: "include" };
const responseHeaders = { "access-control-allow-origin": request.origin, "access-control-allow-credentials": "true" };
console.log(responseHeaders);

// CSRF 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const session = { csrfToken: "known-token" };
const request = { body: { csrfToken: "known-token" } };
console.log(request.body.csrfToken === session.csrfToken);

// DOM 기반 XSS 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const userInput = "<img src=x onerror=alert(1)>";
const safeText = userInput.replaceAll("<", "&lt;").replaceAll(">", "&gt;");
console.log(safeText);

// SQL 인젝션 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const input = "ada@example.com";
const sql = "SELECT * FROM users WHERE email = ?";
const params = [input];
console.log(sql, params);

// 입력 검증 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
function isValidPage(value) { return Number.isInteger(value) && value >= 1 && value <= 100; }
console.log(isValidPage(3));
console.log(isValidPage(-1));

// 속도 제한(Rate Limiting) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const hits = [1, 2, 3, 4];
const limit = 3;
console.log(hits.length <= limit ? "allow" : "block");

// API 게이트웨이 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const gateway = req => req.path.startsWith("/users") ? "user-service" : "default-service";
console.log(gateway({ path: "/users/1" }));

// 로드 밸런서 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const servers = ["app1", "app2", "app3"];
let next = 0;
function pick() { const server = servers[next++ % servers.length]; return server; }
console.log(pick(), pick());

// 역방향 프록시(Reverse Proxy) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const reverseProxy = req => ({ upstream: req.host === "api.example.com" ? "api-server" : "web-server" });
console.log(reverseProxy({ host: "api.example.com" }).upstream);

// 정방향 프록시(Forward Proxy) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const proxyRequest = { client: "browser", target: "https://example.com" };
console.log(`${proxyRequest.client} -> proxy -> ${proxyRequest.target}`);

// CDN 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const assetUrl = "https://cdn.example.com/app.js";
const isCdn = assetUrl.includes("cdn.");
console.log(isCdn);

// WebSocket 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const socketState = { open: true, messages: [] };
if (socketState.open) socketState.messages.push("ping");
console.log(socketState.messages);

// SSE(Server-Sent Events) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const event = `data: ${JSON.stringify({ progress: 50 })}\n\n`;
console.log(event);

// 롱 폴링 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
async function longPoll(hasEvent) { return hasEvent ? "new-event" : "timeout"; }
longPoll(true).then(console.log);

// 단방향 통신 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const channel = { from: "server", to: "client", message: "notice" };
console.log(`${channel.from} -> ${channel.to}: ${channel.message}`);

// 양방향 통신 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const messages = [];
messages.push({ from: "client", text: "ping" });
messages.push({ from: "server", text: "pong" });
console.log(messages.map(m => m.text).join("/"));

// REST 원칙 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const resource = "/users/1";
const action = "GET";
console.log(`${action} ${resource}`);

// RESTful 설계 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const api = { listUsers: "GET /users", createUser: "POST /users", updateUser: "PUT /users/{id}" };
console.log(api.createUser);

// HATEOAS 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const response = { id: 1, name: "Ada", links: [{ rel: "orders", href: "/users/1/orders" }] };
console.log(response.links[0].href);

// GraphQL 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const query = `{ user(id: 1) { name email } }`;
const selectedFields = query.match(/name|email/g);
console.log(selectedFields);

// gRPC 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const protoMethod = { service: "UserService", method: "GetUser", request: { id: 1 } };
console.log(`${protoMethod.service}.${protoMethod.method}`);

// OpenAPI/Swagger 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const spec = { openapi: "3.0.0", paths: { "/users": { get: { summary: "list users" } } } };
console.log(Object.keys(spec.paths));

// 페이지네이션(Pagination) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const items = ["a", "b", "c", "d"];
const page = items.slice(0, 2);
console.log(page);

// 필터링/정렬 API 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const products = [{ name: "pen", price: 1000 }, { name: "bag", price: 30000 }];
const result = products.filter(p => p.price < 5000).sort((a, b) => a.price - b.price);
console.log(result.map(p => p.name));

// 버전 관리(API Versioning) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const requestPath = "/v2/users";
const version = requestPath.split("/")[1];
console.log(version);

// 인증 헤더(Authorization) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const headers = { authorization: "Bearer abc.def.ghi" };
console.log(headers.authorization.startsWith("Bearer "));

// Bearer 토큰 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const header = "Bearer secret-token";
const token = header.replace("Bearer ", "");
console.log(token.length > 0);

// API 키 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const request = { query: { api_key: "key_123" } };
console.log(request.query.api_key.startsWith("key_"));

// 웹훅(Webhook) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const webhook = { url: "https://client.example/hook", event: "payment.paid" };
console.log(`POST ${webhook.url} for ${webhook.event}`);

// 서버리스(Serverless) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const handler = async event => ({ statusCode: 200, body: `hello ${event.name}` });
handler({ name: "Ada" }).then(console.log);

// FaaS 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
async function resizeImage(event) { return `resize ${event.file}`; }
resizeImage({ file: "photo.png" }).then(console.log);

// BaaS 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const baas = { auth: true, database: "managed", storage: "managed" };
console.log(Object.keys(baas).join(","));

// 정적 사이트 생성(SSG) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const posts = ["a", "b"];
const html = posts.map(title => `<h1>${title}</h1>`);
console.log(html.join("\n"));

// 서버 사이드 렌더링(SSR) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
function renderUser(user) { return `<h1>${user.name}</h1>`; }
console.log(renderUser({ name: "Ada" }));

// 클라이언트 사이드 렌더링(CSR) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const root = { innerHTML: "" };
const user = { name: "Ada" };
root.innerHTML = `<h1>${user.name}</h1>`;
console.log(root.innerHTML);

// 점진적 웹 앱(PWA) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const manifest = { name: "Study App", display: "standalone", start_url: "/" };
console.log(manifest.display);

// 서비스 워커 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const cache = new Map();
cache.set("/app.js", "cached file");
console.log(cache.has("/app.js"));

// 웹 캐싱 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const cache = new Map();
function get(url) { if (!cache.has(url)) cache.set(url, `response for ${url}`); return cache.get(url); }
console.log(get("/logo.png"));

// ETag 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const etag = "v1-abc";
const ifNoneMatch = "v1-abc";
console.log(etag === ifNoneMatch ? 304 : 200);

// Cache-Control 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const header = "public, max-age=3600";
const maxAge = Number(header.match(/max-age=(\d+)/)[1]);
console.log(maxAge);

// 콘텐츠 협상 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const accept = "application/json";
const responseType = accept.includes("json") ? "json" : "html";
console.log(responseType);

// 멱등성(Idempotency) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const state = { deleted: false };
function deleteOnce() { state.deleted = true; return state.deleted; }
console.log(deleteOnce(), deleteOnce());

// 압축(Gzip/Brotli) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const text = "hello ".repeat(10);
console.log("원본 길이:", text.length);
console.log("압축은 서버 설정이나 zlib로 적용합니다.");

// HTTPS 리다이렉션 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
function redirectToHttps(url) { return url.replace(/^http:/, "https:"); }
console.log(redirectToHttps("http://example.com/login"));

// TLS 핸드셰이크 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const handshake = ["ClientHello", "ServerHello", "Certificate", "Finished"];
console.log(handshake.join(" -> "));

// 인증서(Certificate) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const cert = { subject: "example.com", issuer: "CA", valid: true };
console.log(cert.valid && cert.subject === "example.com");

// HTTP/2 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const features = ["multiplexing", "header compression", "stream priority"];
console.log(features.includes("multiplexing"));

// HTTP/3 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const protocol = { http: 3, transport: "QUIC/UDP" };
console.log(`${protocol.http} over ${protocol.transport}`);

// DNS 조회 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const dnsRecord = { "example.com": "93.184.216.34" };
console.log(dnsRecord["example.com"]);

// URL 파싱 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const url = new URL("https://example.com/users?id=1#profile");
console.log(url.protocol, url.hostname, url.pathname, url.searchParams.get("id"));

// 쿼리 파라미터 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const url = new URL("https://api.example.com/items?page=2&sort=name");
console.log(url.searchParams.get("page"));

// 경로 파라미터 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const pattern = /^\/users\/(?<id>\d+)$/;
const match = "/users/42".match(pattern);
console.log(match.groups.id);

// Same-Origin Policy 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const a = new URL("https://example.com:443/a");
const b = new URL("https://example.com/b");
console.log(a.origin === b.origin);

// 프리플라이트 요청(Preflight) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const preflight = { method: "OPTIONS", headers: ["Access-Control-Request-Method", "Access-Control-Request-Headers"] };
console.log(preflight.method);

// Content-Type 헤더 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const headers = { "content-type": "application/json" };
const isJson = headers["content-type"].includes("json");
console.log(isJson);

// 멀티파트(Multipart) 요청 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const form = new FormData();
form.append("title", "profile");
console.log(form.has("title"));

// HEAD/OPTIONS 메서드 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const methods = { HEAD: "headers only", OPTIONS: "allowed methods" };
console.log(methods.OPTIONS);

// PATCH 메서드 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const user = { name: "Ada", nickname: "A" };
const patch = { nickname: "Lovelace" };
console.log({ ...user, ...patch });

// Base64 인코딩 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const encoded = Buffer.from("hello").toString("base64");
const decoded = Buffer.from(encoded, "base64").toString("utf8");
console.log(encoded, decoded);

// URL 인코딩(퍼센트) 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const raw = "검색어=웹 개발";
const encoded = encodeURIComponent(raw);
console.log(encoded);
console.log(decodeURIComponent(encoded));

// 웹소켓 핸드셰이크 예시: Node.js 또는 브라우저 콘솔에서 실행 가능한 코드
const requestHeaders = { upgrade: "websocket", connection: "Upgrade", "sec-websocket-key": "abc" };
const canUpgrade = requestHeaders.upgrade === "websocket";
console.log(canUpgrade);
